const assetList=document.querySelector('#asset-list');let allAssets=[];let currentAsset=null;let currentDetail=null;
async function load(){const h=await fetch('/api/health').then(r=>r.json());window.GEMINI_REVIEW_ENABLED=!!h.gemini_review_enabled;window.AGENT_DRAFT_ENABLED=!!h.agent_draft_enabled;document.querySelector('#data-source').textContent=h.data_source==='bigquery'?'BigQuery connected':'Supplied equipment records';const overviewSource=document.querySelector('#overview-data-source');if(overviewSource)overviewSource.textContent=h.data_source==='bigquery'?'BigQuery connected':'Supplied equipment records';const d=await fetch('/api/equipment?per_page=1').then(r=>r.json());allAssets=[];document.querySelector('#asset-count').textContent=d.total+' of '+d.counts.ledger_records+' ledger / '+d.counts.telemetry_ids+' telemetry';const overviewCount=document.querySelector('#overview-asset-count');if(overviewCount)overviewCount.textContent=d.total;renderAssets();syncAssistantState();loadSharedAsset();}
async function loadSharedAsset(){const id=new URLSearchParams(location.search).get('asset');if(!id)return;try{const r=await fetch('/api/equipment/'+encodeURIComponent(id));const j=await r.json();if(!r.ok||!j.telemetry)throw new Error('shared asset unavailable: not telemetry-backed');if(typeof showScreen==='function')showScreen('equipment');const note=document.querySelector('#shared-view-note');if(note){note.hidden=false;note.textContent='Shared view loaded for '+id;}await selectDirectory(id);document.body.dataset.assetLoaded=id;}catch(e){const note=document.querySelector('#shared-view-note');if(note){note.hidden=false;note.textContent='Shared view unavailable: '+e.message;}}}
function renderAssets(){const q=document.querySelector('#search').value.toLowerCase();assetList.innerHTML='';allAssets.filter(a=>(a.asset_id+a.equipment_type_code).toLowerCase().includes(q)).forEach(a=>{const b=document.createElement('button');b.className='asset-button'+(currentAsset===a.asset_id?' selected':'');b.innerHTML=`<div class="asset-code">Equipment ${escapeHtml(a.equipment_type_code||'Unknown')}</div><div class="asset-id">${escapeHtml(a.asset_id)}</div><div class="asset-id">${a.observation_count} readings · latest ${escapeHtml(a.latest_observation||'unknown')}</div>`;b.onclick=()=>selectAsset(a.asset_id);assetList.appendChild(b);});}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function selectAsset(id){currentAsset=id;syncAssistantState();renderAssets();currentDetail=await fetch('/api/assets/'+encodeURIComponent(id)).then(r=>r.json());document.querySelector('#empty-state').hidden=true;document.querySelector('#asset-detail').hidden=false;document.querySelector('#asset-title').textContent='Equipment '+currentDetail.equipment_type_code;document.querySelector('#asset-meta').textContent=`${id} · ${currentDetail.observation_count} observations · latest ${currentDetail.latest_observation}`;const m=document.querySelector('#metric-grid');const labels=[['Observation count',currentDetail.observation_count],['Latest reading',currentDetail.latest_observation],['Phase current spread',currentDetail.phase_current_spread_pct==null?'Not available':currentDetail.phase_current_spread_pct+'%'],['Assessment status','Review only']];m.innerHTML=labels.map(x=>`<div class="metric"><label>${escapeHtml(x[0])}</label><strong>${escapeHtml(x[1])}</strong></div>`).join('');const select=document.querySelector('#measurement-select');const names=[...new Set(currentDetail.history.map(x=>x.measurement_name))].sort();select.innerHTML=names.map(n=>`<option>${escapeHtml(n)}</option>`).join('');select.onchange=renderChart;renderWarnings();renderChart();document.querySelector('#sources').textContent='Source exports: '+currentDetail.source_files.join(', ');document.querySelector('#explanation').hidden=true;}
function renderWarnings(){document.querySelector('#warnings').innerHTML=currentDetail.quality_warnings.map(w=>`<li>${escapeHtml(w)}</li>`).join('');}
function renderChart(){if(!currentDetail)return;const name=document.querySelector('#measurement-select').value;const points=currentDetail.history.filter(x=>x.measurement_name===name&&x.measurement_value!==null).slice(-120);const box=document.querySelector('#chart');if(points.length<2){box.textContent=points.length?'Single observation — no trend to display':'No numeric history available for this measurement.';return;}const vals=points.map(x=>Number(x.measurement_value));const min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;const W=900,H=170,pad=25;const coords=vals.map((v,i)=>`${pad+i*(W-2*pad)/Math.max(1,vals.length-1)},${H-pad-(v-min)*(H-2*pad)/range}`).join(' ');box.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${escapeHtml(name)} over time"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="#dce5eb"/><polyline points="${coords}" fill="none" stroke="#176b87" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><text x="${pad}" y="14">${escapeHtml(max.toFixed(3))}</text><text x="${pad}" y="${H-2}">${escapeHtml(min.toFixed(3))}</text><text x="${W-pad}" y="${H-2}" text-anchor="end">${escapeHtml(points[points.length-1].observed_at)}</text><text x="${pad+5}" y="${H-2}">${escapeHtml(points[0].observed_at)}</text></svg>`;}
document.querySelector('#search').addEventListener('input',renderAssets);async function loadDefects(q=''){const r=await fetch('/api/defects?q='+encodeURIComponent(q));const data=await r.json();const box=document.querySelector('#defect-results');box.innerHTML=data.items.map(x=>`<article class="defect-item"><div class="defect-top"><strong>${escapeHtml(x.defect_description||'Unspecified defect')}</strong><span class="severity">${escapeHtml(x.severity||'Unclassified')}</span></div><p>${escapeHtml(x.equipment_type||'')} ${escapeHtml(x.equipment_subtype||'')} · ${escapeHtml(x.defect_location||'')}</p><small>${escapeHtml(x.classification_basis||'')}</small><p class="action">${escapeHtml(x.remediation_method||x.remediation_work_type||'No action listed')}</p></article>`).join('')||'<p class="muted">No matching reference rows.</p>';document.querySelector('#defect-search').dataset.count=data.count;}document.querySelector('#defect-search').addEventListener('input',e=>loadDefects(e.target.value));loadDefects();load().catch(e=>{document.querySelector('#data-source').textContent='Data unavailable';assetList.textContent=e.message;});let currentMonitoring=null,currentCase=null,caseKey=null;
const ALLOWED={open:['in_review','evidence_required'],in_review:['completed','evidence_required'],evidence_required:['in_review'],completed:[]};
function showError(id,msg){const e=document.querySelector(id);e.hidden=!msg;e.textContent=msg||'';}
async function genMonitoring(){if(!currentAsset)return;const requestedAsset=currentAsset;const b=document.querySelector('#monitoring-button');b.disabled=true;showError('#monitoring-error','');const modelStatus=document.querySelector('#monitoring-model-status');if(modelStatus)modelStatus.textContent='';try{const r=await fetch('/api/monitoring-reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset_id:requestedAsset})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Monitoring request failed');currentMonitoring=j;caseKey=null;document.querySelector('#monitoring-result').hidden=false;document.querySelector('#monitoring-case-line').textContent='';const m=[['Readiness route',j.readiness.review_route||'unknown'],['Fault state',j.readiness.fault_state||'unknown'],['Observations',j.population.observation_count],['Excluded (other equipment)',j.population.non_target_scope_excluded]];document.querySelector('#monitoring-metrics').innerHTML=m.map(x=>`<div class="metric"><label>${escapeHtml(x[0])}</label><strong>${escapeHtml(String(x[1]))}</strong></div>`).join('');document.querySelector('#monitoring-codes').innerHTML=`<table class="data-table"><thead><tr><th>Code</th><th>n</th><th>Min</th><th>Max</th><th>Mean</th></tr></thead><tbody>`+Object.entries(j.descriptive).map(([c,s])=>`<tr><td>${escapeHtml(c)}</td><td>${s.observation_count}</td><td>${s.minimum}</td><td>${s.maximum}</td><td>${s.mean}</td></tr>`).join('')+`</tbody></table>`;document.querySelector('#monitoring-candidates').innerHTML=j.review_candidates.length?j.review_candidates.map(c=>`<p>${escapeHtml(c.measurement_type_code)}: ${c.candidate_count} candidate(s), method ${escapeHtml(c.method)} (k=${c.params.k}) — review only</p>`).join(''):'<p class="muted">No review candidates.</p>';const reg=j.unknowns.evidence_register;document.querySelector('#monitoring-unknowns').innerHTML=j.unknowns.quality_warnings.map(w=>`<li>${escapeHtml(w)}</li>`).join('')+`<li>Units: ${escapeHtml(j.unknowns.units)}; timezone: ${escapeHtml(j.unknowns.timezone)}. Evidence register: ${reg.pending} pending, ${reg.unverified} unverified, ${reg.verified} verified.</li>`;document.querySelector('#monitoring-unsupported').innerHTML=j.unsupported.map(u=>`<li>${escapeHtml(u.conclusion)}: ${escapeHtml(u.state)} — ${escapeHtml(u.reason)}</li>`).join('');if(window.GEMINI_REVIEW_ENABLED){const host=document.querySelector('.gemini-review');if(host){if(modelStatus)modelStatus.textContent='Generating a context-grounded Gemini review for this equipment…';const ok=await generateGeminiReview(requestedAsset,host);if(modelStatus)modelStatus.textContent=ok?'Gemini review is shown in AI summary preview below.':'Gemini could not return a usable review; the descriptive monitoring results remain available.';}}else if(modelStatus){modelStatus.textContent='Gemini review is disabled in this deployment. Descriptive monitoring results are shown above.';}}catch(e){showError('#monitoring-error',e.message);}finally{b.disabled=false;}}
document.querySelector('#monitoring-button').onclick=genMonitoring;
async function createCase(){if(!currentMonitoring)return;const b=document.querySelector('#case-button');b.disabled=true;try{if(!caseKey)caseKey=(crypto.randomUUID?crypto.randomUUID():String(Date.now()));const r=await fetch('/api/review-cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset_id:currentMonitoring.request_asset_id,idempotency_key:caseKey})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Case creation failed');document.querySelector('#monitoring-case-line').textContent=(j.replayed?'Existing case (duplicate prevented): ':'New case: ')+j.case_id+' · '+j.status+' · v'+j.version;loadQueue();}catch(e){showError('#monitoring-error',e.message);}finally{b.disabled=false;}}
document.querySelector('#case-button').onclick=createCase;
async function loadQueue(){const box=document.querySelector('#queue-list');box.innerHTML='<p class="muted">Loading…</p>';showError('#queue-error','');try{const q=new URLSearchParams({asset:document.querySelector('#queue-asset').value,status:document.querySelector('#queue-status').value});const r=await fetch('/api/review-cases?'+q);const j=await r.json();if(!r.ok)throw new Error(j.error||'Queue load failed');document.querySelector('#queue-count').textContent=j.length;box.innerHTML=j.length?j.map(c=>`<button class="asset-button" data-case="${escapeHtml(c.case_id)}"><div class="asset-code">${escapeHtml(c.status)} · v${c.version}</div><div class="asset-id">${escapeHtml(c.case_id)}</div><div class="asset-id">${escapeHtml(c.asset_id)} · ${escapeHtml(c.updated_at||'')}</div></button>`).join(''):'<p class="muted">No review cases yet. Generate a monitoring review and create a case to begin.</p>';box.querySelectorAll('[data-case]').forEach(x=>x.onclick=()=>selectCase(x.dataset.case));}catch(e){box.innerHTML='';showError('#queue-error',e.message);}}
document.querySelector('#queue-reload').onclick=loadQueue;document.querySelector('#queue-asset').addEventListener('input',loadQueue);document.querySelector('#queue-status').onchange=loadQueue;
async function selectCase(id){showError('#case-error','');try{const r=await fetch('/api/review-cases/'+encodeURIComponent(id));const j=await r.json();if(!r.ok)throw new Error(j.error||'Case load failed');currentCase=j;document.querySelector('#case-detail').hidden=false;document.querySelector('#case-title').textContent='Case '+j.case_id;document.querySelector('#case-meta').textContent=`${j.asset_id} · v${j.version} · created ${j.created_at}`;document.querySelector('#case-status').textContent=j.status;const s=j.monitoring.snapshot,dig=j.monitoring.digest_sha256;document.querySelector('#case-monitoring').innerHTML=`<p class="muted">Pinned monitoring ${escapeHtml(j.monitoring.workflow_version)} · digest ${escapeHtml(String(dig).slice(0,12))}… · readiness ${escapeHtml(s.readiness.review_route)} · fault ${escapeHtml(s.readiness.fault_state)} · observations ${s.population.observation_count}</p>`;document.querySelector('#case-history').innerHTML=j.history.map(e=>`<p><strong>#${e.seq} ${escapeHtml(e.event)}</strong> ${escapeHtml(e.from_status||'—')} → ${escapeHtml(e.to_status)} · ${escapeHtml(e.at)}${e.note?' · '+escapeHtml(e.note):''}${e.actor&&e.actor.label?' · reviewer '+escapeHtml(e.actor.label)+' (self-asserted, unverified)':''}</p>`).join('');document.querySelector('#case-actions').innerHTML=(ALLOWED[j.status]||[]).map(t=>`<button data-t="${t}">${escapeHtml(t)}</button>`).join('')||'<p class="muted">Terminal state: no further transitions.</p>';document.querySelectorAll('#case-actions [data-t]').forEach(x=>x.onclick=()=>doTransition(x.dataset.t));}catch(e){showError('#case-error',e.message);}}
async function doTransition(to){showError('#case-error','');try{const r=await fetch('/api/review-cases/'+encodeURIComponent(currentCase.case_id)+'/transitions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({from_version:currentCase.version,to_status:to})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Transition failed');selectCase(currentCase.case_id);loadQueue();}catch(e){showError('#case-error',e.message+' (reloaded state shown; nothing overwritten)');if(currentCase)selectCase(currentCase.case_id);}}
document.querySelector('#note-button').onclick=async()=>{if(!currentCase)return;showError('#case-error','');try{const r=await fetch('/api/review-cases/'+encodeURIComponent(currentCase.case_id)+'/notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({from_version:currentCase.version,note:document.querySelector('#note-text').value,reviewer:document.querySelector('#note-reviewer').value||undefined})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Note failed');document.querySelector('#note-text').value='';selectCase(currentCase.case_id);}catch(e){showError('#case-error',e.message);}};
loadQueue();
async function loadEvidence(){try{const r=await fetch('/api/evidence-gaps');const j=await r.json();if(!r.ok)throw new Error(j.error||'Evidence status failed');document.querySelector('#evidence-summary').textContent=`${j.total} items tracked · ${j.verified} verified · ${j.total-j.verified} awaiting evidence or review`;document.querySelector('#evidence-verified').textContent=`${j.verified} verified`;const overviewEvidence=document.querySelector('#overview-evidence-count');if(overviewEvidence)overviewEvidence.textContent=`${j.verified} verified · ${j.total-j.verified} pending or unverified`;document.querySelector('#evidence-list').innerHTML=j.items.map(x=>`<p><strong>${escapeHtml(x.evidence_id)}</strong> <span class="severity">${escapeHtml(x.status)}</span><br><span class="muted">${escapeHtml(x.question)} Blocks: ${escapeHtml((x.blocks||[]).join('; '))}</span></p>`).join('');}catch(e){const b=document.querySelector('#evidence-error');b.hidden=false;b.textContent=e.message;}}
