// Frontend-only product previews and workspace navigation.
const screenTitles={overview:'Overview',equipment:'Equipment Status',monitoring:'Monitoring Review',reviews:'Review Queue',evidence:'Evidence Register',reference:'Technical Reference',agent:'Agent Workspace',knowledge:'Knowledge Library',reports:'Reports',chat:'AI Smart Assistant',meteorological:'Environmental Data'};
function showScreen(name){const target=name==='monitoring'?'equipment':name;document.querySelectorAll('[data-screen]').forEach(node=>{node.hidden=node.dataset.screen!==target;});document.querySelectorAll('[data-nav]').forEach(node=>{if(node.matches('.nav-link')){node.classList.toggle('active',node.dataset.nav===name||(name==='monitoring'&&node.dataset.nav==='monitoring'));if(node.classList.contains('active'))node.setAttribute('aria-current','page');else node.removeAttribute('aria-current');}});const context=document.querySelector('#page-context');if(context)context.textContent=screenTitles[name]||screenTitles.overview;if(name==='chat')syncAssistantState();if(name==='monitoring'){requestAnimationFrame(()=>document.querySelector('#monitoring')?.scrollIntoView({behavior:'smooth',block:'start'}));}window.scrollTo({top:0,behavior:'smooth'});}
function screenFromHash(){const raw=decodeURIComponent((location.hash||'').replace(/^#/,'')).trim().toLowerCase();return [...document.querySelectorAll('[data-screen]')].map(n=>n.dataset.screen).includes(raw)?raw:'overview';}
document.querySelectorAll('[data-nav]').forEach(node=>node.addEventListener('click',event=>{event.preventDefault();const next=node.dataset.nav;if((location.hash||'').replace(/^#/,'')===next){showScreen(next);}else{location.hash=next;}}));
window.addEventListener('hashchange',()=>showScreen(screenFromHash()));
showScreen(screenFromHash());
let dirPage=1;const DIR_PER=50;
function dirFiltered(){return document.querySelector('#dir-type').value||document.querySelector('#dir-coverage').value||document.querySelector('#search').value;}
async function loadDirectory(reset){if(reset)dirPage=1;const q=new URLSearchParams({q:document.querySelector('#search').value,type:document.querySelector('#dir-type').value,coverage:document.querySelector('#dir-coverage').value,sort:document.querySelector('#dir-sort').value,page:String(dirPage),per_page:String(DIR_PER)});try{const r=await fetch('/api/equipment?'+q);const j=await r.json();if(!r.ok)throw new Error(j.error||'Directory load failed');if(reset)assetList.innerHTML='';document.querySelector('#asset-count').textContent=j.total+' telemetry-backed · '+j.counts.exact_matches+' exact-ID ledger matches';j.items.forEach(a=>{const b=document.createElement('button');b.className='asset-button';b.innerHTML=`<div class="asset-code">${escapeHtml(coverageLabel(a.coverage))} · ${escapeHtml((a.equipment_type_codes||[]).join(',')||a.ast_type||'untyped')}</div><div class="asset-id">${escapeHtml(a.asset_id)}</div><div class="asset-id">${a.observation_count} readings</div>`;b.onclick=()=>selectDirectory(a.asset_id);assetList.appendChild(b);});document.querySelector('#dir-more').hidden=!(j.page* j.per_page<j.total);}catch(e){assetList.textContent=e.message;}}
document.querySelector('#dir-type').onchange=()=>loadDirectory(true);document.querySelector('#dir-coverage').onchange=()=>loadDirectory(true);document.querySelector('#dir-sort').onchange=()=>loadDirectory(true);document.querySelector('#dir-more').onclick=()=>{dirPage++;loadDirectory(false);};
const _origRenderAssets=renderAssets;renderAssets=function(){loadDirectory(true);};
const ID_MATCH_CAVEAT='Ledger and telemetry share this exact ID; shared IDs are not proof of the same physical asset.';
const LEDGER_LABELS={ast_type:'Equipment class (ledger code)',voltage_level_en:'Voltage',psr_state_en:'Operating state',manufacturer:'Manufacturer code',model:'Model',insulation_medium_en:'Insulation',operate_date_iso:'In service since',manufacture_date_iso:'Manufactured'};
const LEDGER_KEYS=['ast_type','voltage_level_en','psr_state_en','manufacturer','model','insulation_medium_en','operate_date_iso','manufacture_date_iso'];
function ledgerTable(ledger){return `<h4>Equipment profile</h4><table class="data-table"><tbody>`+LEDGER_KEYS.map(k=>`<tr><td>${escapeHtml(LEDGER_LABELS[k])}</td><td>${escapeHtml(String(ledger[k]??'Not in source'))}</td></tr>`).join('')+`</tbody></table><p class="muted">Ledger codes are shown as codes; ast_type meanings are unverified.</p>`;}
function coverageLabel(coverage){return coverage==='both'?'both · exact ID match':coverage;}
async function selectDirectory(id){try{const r=await fetch('/api/equipment/'+encodeURIComponent(id));const j=await r.json();if(!r.ok)throw new Error(j.error||'Equipment load failed');if(j.telemetry&&(j.telemetry.equipment_type_codes||[]).includes('0408001')){await selectAsset(id);return;}currentAsset=id;syncAssistantState();document.querySelector('#empty-state').hidden=true;document.querySelector('#asset-detail').hidden=true;const box=document.querySelector('#directory-detail');box.hidden=false;let html=`<div class="detail-head"><div><p class="eyebrow">SELECTED EQUIPMENT</p><h2>${escapeHtml(id)}</h2><p class="muted">${escapeHtml(coverageLabel(j.coverage))}</p></div><span class="tag">${escapeHtml(coverageLabel(j.coverage))}</span></div>`;if(j.coverage==='both')html+=`<p class="muted">${escapeHtml(ID_MATCH_CAVEAT)}</p>`;html+=`<p class="muted">${escapeHtml(j.note||'')}</p>`;if(j.ledger){html+=ledgerTable(j.ledger);}else if(j.telemetry){html+=`<p class="muted">No exact-ID ledger match for this equipment.</p>`;}if(j.telemetry){const allStamps=new Set();Object.values(j.telemetry.readings_by_code||{}).forEach(s=>(s.points||[]).forEach(p=>allStamps.add(String(p[0]))));window._dirSeries=j.telemetry.readings_by_code||{};window._dirPage=0;html+=`<div class="stat-cards"><div class="stat-card"><span class="stat-circle">${j.telemetry.observation_count}</span><span>readings</span></div><div class="stat-card"><span class="stat-circle">${j.ledger?2:1}</span><span>sources matched</span></div></div><p class="muted">Latest ${escapeHtml(j.telemetry.latest_observation||'unknown')} · sources ${(j.telemetry.source_files||[]).map(escapeHtml).join(', ')}</p><p class="muted">${escapeHtml(j.value_caveat||'')}</p>`;if(allStamps.size<2){const stamp=[...allStamps][0]||'unknown';html+=`<p class="muted">Single shared snapshot timestamp: ${escapeHtml(stamp)}</p><h4>Observed readings</h4><table class="data-table"><thead><tr><th>Measurement (code)</th><th>Raw value</th><th>Timestamp</th></tr></thead><tbody>`+Object.entries(window._dirSeries).map(([c,s])=>`<tr><td>${escapeHtml(s.measurement_name||c)} (${escapeHtml(c)})</td><td>${escapeHtml(s.latest_value===null||s.latest_value===undefined?'Not recorded':String(s.latest_value))}</td><td>${escapeHtml(s.latest_observation||'')}</td></tr>`).join('')+`</tbody></table>`;}else{html+=`<div class="queue-filters"><select id="dir-code-select" aria-label="Measurement code"></select></div><div id="dir-summary" class="muted"></div><div id="dir-chart" class="chart"></div><div id="dir-table"></div>`;}}if(j.analysis_note)html+=`<p class="muted">${escapeHtml(j.analysis_note)}</p>`;if(j.telemetry)html+=`<ul class="quality"><li>Measurement units and scaling have not been confirmed.</li><li>Timestamp timezone is unconfirmed.</li></ul>`;box.innerHTML=html;mountAssetMapping(id,box);const sel=document.querySelector('#dir-code-select');if(sel&&j.telemetry){sel.innerHTML=Object.keys(window._dirSeries).map(c=>`<option>${escapeHtml(c)}</option>`).join('');sel.onchange=()=>{window._dirPage=0;renderDirChart();};renderDirChart();}}catch(e){document.querySelector('#directory-detail').hidden=false;document.querySelector('#directory-detail').textContent=e.message;}}
function shortTick(stamp){const m=String(stamp).match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})/);return m?`${m[2]}-${m[3]} ${m[4]}:${m[5]}`:String(stamp);}
const DIR_PAGE_SIZE=25;
function renderDirChart(){const sel=document.querySelector('#dir-code-select');const box=document.querySelector('#dir-chart');if(!sel||!box)return;const series=(window._dirSeries||{})[sel.value];const summary=document.querySelector('#dir-summary');const table=document.querySelector('#dir-table');if(!series){box.textContent='No numeric history available for this measurement.';return;}const points=series.points.filter(p=>p[1]!==null&&p[1]!==undefined).map(p=>[String(p[0]),Number(p[1])]).filter(p=>!isNaN(p[1]));if(points.length<2){box.textContent=points.length?'Single observation — no trend to display':'No numeric history available for this measurement.';if(table)table.innerHTML='';if(summary)summary.textContent='';return;}const vals=points.map(p=>p[1]);const min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;const W=900,H=170,pad=25;const coords=vals.map((v,i)=>`${pad+i*(W-2*pad)/Math.max(1,vals.length-1)},${H-pad-(v-min)*(H-2*pad)/range}`).join(' ');const ticks=[0,1,2,3,4].map(k=>Math.round(k*(vals.length-1)/4));box.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${escapeHtml(sel.value)} over time, raw values, units unconfirmed"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="#dce5eb"/><polyline points="${coords}" fill="none" stroke="#176b87" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`+ticks.map(i=>`<text x="${pad+i*(W-2*pad)/Math.max(1,vals.length-1)}" y="${H-2}" text-anchor="middle">${escapeHtml(shortTick(points[i][0]))}</text>`).join('')+`</svg>`;const allZero=vals.every(v=>v===0);if(summary)summary.textContent=`${series.measurement_name||sel.value} (${sel.value}): ${vals.length} observations · latest ${vals[vals.length-1]} · min ${min} · max ${max}`+(allZero?' · All recorded values are 0':'');if(table){const pages=Math.max(1,Math.ceil(points.length/DIR_PAGE_SIZE));window._dirPage=Math.min(window._dirPage||0,pages-1);const slice=points.slice(window._dirPage*DIR_PAGE_SIZE,(window._dirPage+1)*DIR_PAGE_SIZE);table.innerHTML=`<p class="muted">Exact timestamps and values (page ${window._dirPage+1} of ${pages})</p><table class="data-table"><thead><tr><th>Timestamp</th><th>Raw value</th></tr></thead><tbody>`+slice.map(p=>`<tr><td>${escapeHtml(p[0])}</td><td>${escapeHtml(p[1]===null||p[1]===undefined||isNaN(p[1])?'Not recorded':String(p[1]))}</td></tr>`).join('')+`</tbody></table>`+(pages>1?`<div class="queue-filters"><button id="dir-prev"${window._dirPage===0?' disabled':''}>Previous</button><button id="dir-next"${window._dirPage>=pages-1?' disabled':''}>Next</button></div>`:'');const prev=document.querySelector('#dir-prev');if(prev)prev.onclick=()=>{window._dirPage--;renderDirChart();};const next=document.querySelector('#dir-next');if(next)next.onclick=()=>{window._dirPage++;renderDirChart();};}}

async function renderLedgerFacts(id){try{const r=await fetch('/api/equipment/'+encodeURIComponent(id));const j=await r.json();if(!r.ok||!j.ledger)return;let box=document.querySelector('#ledger-facts');if(!box){box=document.createElement('div');box.id='ledger-facts';document.querySelector('#sources').after(box);}box.innerHTML=ledgerTable(j.ledger)+`<p class="muted">${escapeHtml(ID_MATCH_CAVEAT)}</p>`;}catch(e){}}
const _origSelectAsset=selectAsset;selectAsset=async function(id){document.querySelector('#directory-detail').hidden=true;const oldFacts=document.querySelector('#ledger-facts');if(oldFacts)oldFacts.remove();document.querySelector('#metric-grid').hidden=false;document.querySelector('.chart-section').hidden=false;document.querySelector('.quality').hidden=false;const result=await _origSelectAsset(id);renderLedgerFacts(id);mountAssetMapping(id,document.querySelector('#asset-detail'));mountGeminiReview(id,document.querySelector('#asset-detail'));return result;};
document.querySelector('#search').removeEventListener('input',_origRenderAssets);
document.querySelector('#search').addEventListener('input',()=>renderAssets());
async function loadCoverage(){
  const err=document.querySelector('#coverage-error'),cards=document.querySelector('#coverage-cards'),sources=document.querySelector('#coverage-sources'),unresolved=document.querySelector('#coverage-unresolved'),note=document.querySelector('#coverage-fallback-note'),sourceHeading=document.querySelector('#coverage-source-heading'),unresolvedHeading=document.querySelector('#coverage-unresolved-heading');
  err.hidden=true;note.hidden=true;sourceHeading.hidden=false;unresolvedHeading.hidden=false;sources.hidden=false;unresolved.hidden=false;
  try{
    const r=await fetch('/api/lineage'),j=await r.json();
    if(!r.ok)throw new Error(j.error||'Lineage load failed');
    const e=j.equipment;
    cards.innerHTML=[['Telemetry equipment',e.telemetry_ids],['Telemetry observations',e.telemetry_observations],['Ledger records',e.ledger_ids],['Exact ID matches',e.exact_id_matches]].map(x=>`<div class="metric"><label>${escapeHtml(x[0])}</label><strong>${escapeHtml(String(x[1]))}</strong></div>`).join('')+`<p class="muted">${escapeHtml(e.match_note)}</p>`;
    sources.innerHTML=`<table class="data-table"><thead><tr><th>Source family</th><th>Status</th><th>Counts</th><th>Translation/review</th><th>Retrieval</th></tr></thead><tbody>`+j.sources.map(s=>`<tr><td>${escapeHtml(s.family)}</td><td>${escapeHtml(s.status)}</td><td>${escapeHtml([s.records,s.observations].filter(v=>v!==null&&v!==undefined).join(' / ')||'—')}</td><td>${escapeHtml(s.translation_status)} / ${escapeHtml(s.review_status)}</td><td>${escapeHtml(s.retrieval)}</td></tr>`).join('')+`</tbody></table>`;
    unresolved.innerHTML='<ul class="quality">'+j.unresolved.map(u=>`<li>${escapeHtml(u)}</li>`).join('')+'</ul>';
  }catch(e){
    try{
      const r=await fetch('/api/equipment?coverage=all&per_page=1'),j=await r.json();
      if(!r.ok)throw new Error(j.error||'Coverage load failed');
      const c=j.counts||{},unmatched=Array.isArray(c.unmatched_telemetry_ids)?c.unmatched_telemetry_ids.length:0;
      cards.innerHTML=[['Telemetry assets',c.telemetry_ids||0],['Ledger records',c.ledger_records||0],['Exact ID matches',c.exact_matches||0],['Telemetry IDs without an exact ledger match',unmatched]].map(x=>`<div class="metric"><label>${escapeHtml(x[0])}</label><strong>${escapeHtml(String(x[1]))}</strong></div>`).join('');
      sources.innerHTML='';unresolved.innerHTML='';sourceHeading.hidden=true;unresolvedHeading.hidden=true;sources.hidden=true;unresolved.hidden=true;
      note.textContent='Counts are based on the ledger and telemetry included in this deployment. Use the relationship explorer to inspect a specific equipment record.';note.hidden=false;
    }catch(fallbackError){err.hidden=false;err.textContent=fallbackError.message;}
  }
}
async function loadLineage(){const id=document.querySelector('#lineage-asset').value.trim();const err=document.querySelector('#lineage-error'),box=document.querySelector('#lineage-detail');err.hidden=true;box.innerHTML='';if(!id)return;try{const r=await fetch('/api/lineage/equipment/'+encodeURIComponent(id));const j=await r.json();if(!r.ok)throw new Error(j.error||'Lineage load failed');let html=`<h4>${escapeHtml(j.asset_id)}</h4><p class="muted">${j.telemetry.observation_count} observations · ${escapeHtml((j.telemetry.source_files||[]).join(', '))} · ${escapeHtml(j.telemetry.time_coverage.first||'')} → ${escapeHtml(j.telemetry.time_coverage.last||'')}</p><table class="data-table"><thead><tr><th>Code</th><th>n</th><th>First</th><th>Last</th></tr></thead><tbody>`+Object.entries(j.telemetry.per_code).map(([c,s])=>`<tr><td>${escapeHtml(c)}</td><td>${s.observation_count}</td><td>${escapeHtml(s.first_observation)}</td><td>${escapeHtml(s.last_observation)}</td></tr>`).join('')+`</tbody></table>`;if(j.ledger_match.matched){html+=`<h4>Ledger match (exact ID)</h4><table class="data-table"><tbody>`+Object.entries(j.ledger_match.profile).map(([k,v])=>`<tr><td>${escapeHtml(k)}</td><td>${escapeHtml(String(v??'Not in source'))}</td></tr>`).join('')+`</tbody></table><p class="muted">Locator: ${escapeHtml(j.ledger_match.locator.workbook)} / ${escapeHtml(j.ledger_match.locator.sheet)} / ${escapeHtml(j.ledger_match.locator.key)}</p>`;}else{html+=`<p class="muted">${escapeHtml('No exact ledger ID match; never infer or fuzzy-match a ledger record.')}</p>`;}html+=`<p class="muted">${escapeHtml(j.references_note)}</p>`;if(j.evidence_profile)html+=renderEvidenceProfile(j.evidence_profile);if(j.evidence_review)html+=renderEvidenceReview(j.evidence_review);box.innerHTML=html;}catch(e){err.hidden=false;err.textContent=e.message;}}
function shortHash(v){return v?escapeHtml(String(v).slice(0,12))+'…':'no verifiable hash';}
function provLoc(v){if(!v)return '—';return escapeHtml(v.workbook||v.sheet||v.kind||'source')+(v.key?' · '+escapeHtml(v.key):'');}
function renderEvidenceProfile(p){
  const c=p.context,l=p.link,t=p.telemetry;
  let h='<div id="evidence-profile"><h4>Asset evidence profile</h4>';
  h+='<p class="muted">Recorded evidence for this asset, with its sources and linked measurement history.</p>';
  h+='<h4>Ledger context (recorded in the ledger)</h4>';
  h+='<p class="muted">Translation status '+escapeHtml(String(c.translation_status))+' · review '+escapeHtml(String(c.review_status))+' · '+escapeHtml(String(c.status_label))+'</p>';
  h+='<table class="data-table" id="evidence-context"><thead><tr><th>Field</th><th>Recorded value</th><th>Translated</th><th>Context use</th><th>Provenance</th></tr></thead><tbody>';
  c.fields.forEach(f=>{
    const use=f.usable_for_context?'usable as context':(f.recorded?'recorded, blocked: '+escapeHtml(String(f.blocked_reason_code)):'absent — not in source');
    h+='<tr><td>'+escapeHtml(f.field)+'</td><td>'+(f.value===null||f.value===undefined?'<span class="muted">not in source</span>':escapeHtml(f.value))+'</td><td>'+(f.translated===null||f.translated===undefined?'—':escapeHtml(f.translated))+'</td><td>'+use+'</td><td class="muted">'+provLoc(f.locator)+' · '+shortHash(f.source_sha256)+'</td></tr>';
  });
  h+='</tbody></table>';
  h+='<p class="muted">'+c.recorded_count+' field(s) recorded; '+c.absent_count+' absent: '+escapeHtml((c.absent_fields||[]).join(', ')||'none')+'.</p>';
  if(c.translation_review){const tr=c.translation_review;h+='<p class="muted">Recorded translation review: '+escapeHtml(tr.reviewer_role||'reviewer')+' ('+escapeHtml(tr.reviewed_by||'')+') on '+escapeHtml(tr.reviewed_at||'')+'. Scope: '+escapeHtml(tr.scope||'')+'. Excludes: '+escapeHtml((tr.excludes||[]).join(', '))+'.</p>';}
  h+='<h4>Evidence link</h4>';
  if(l.status==='linked'){
    h+='<p id="evidence-link">Ledger <code>'+escapeHtml(l.ledger_endpoint.evidence_id)+'</code> ↔ telemetry set <code>'+escapeHtml(l.telemetry_endpoint.evidence_id)+'</code> ('+l.telemetry_endpoint.record_count+' record(s)). Method '+escapeHtml(l.matching_method)+'; verification '+escapeHtml(l.verification_status)+'.</p>';
    h+='<p class="muted">Ledger provenance: '+provLoc(l.ledger_endpoint.locator)+' · '+shortHash(l.ledger_endpoint.source_sha256)+'</p>';
  }else{
    h+='<p id="evidence-link">No link asserted ('+escapeHtml(String(l.blocked_reason_code))+'). Method '+escapeHtml(l.matching_method)+'; verification '+escapeHtml(l.verification_status)+'.</p>';
  }
  h+='<p class="muted" id="evidence-link-caveat">'+escapeHtml(l.caveat)+'</p>';
  h+='<h4>Telemetry observations (observed records)</h4>';
  h+='<p class="muted">'+t.observation_count+' observation(s) · '+t.measurement_code_count+' code(s) · '+escapeHtml(t.first_observation)+' → '+escapeHtml(t.last_observation)+' · sources '+escapeHtml((t.source_files||[]).join(', '))+'</p>';
  h+='<p class="muted">Summaries are reproducible over '+t.metrics_scope.evidence_count+' record(s); inventory digest '+shortHash(t.metrics_scope.inventory_digest_sha256)+'. Units/scaling unconfirmed.</p>';
  h+='<table class="data-table"><thead><tr><th>Code</th><th>n</th><th>Min</th><th>Max</th><th>Mean</th></tr></thead><tbody>'+t.descriptive_metrics.map(m=>'<tr><td>'+escapeHtml(m.measurement_type_code)+'</td><td>'+m.observation_count+'</td><td>'+escapeHtml(String(m.minimum))+'</td><td>'+escapeHtml(String(m.maximum))+'</td><td>'+escapeHtml(String(m.mean))+'</td></tr>').join('')+'</tbody></table>';
  h+='<h4>Unavailable evidence</h4><ul class="quality" id="evidence-unsupported">'+p.unsupported_evidence.map(u=>'<li><strong>'+escapeHtml(u.evidence_type)+'</strong> — '+escapeHtml(u.status)+': '+escapeHtml(u.statement)+'</li>').join('')+'</ul>';
  h+='<h4>Unresolved conclusions</h4><ul class="quality" id="evidence-unresolved">'+p.unresolved_conclusions.map(cn=>'<li>'+escapeHtml(cn.dimension)+': '+escapeHtml(cn.status)+'</li>').join('')+'</ul>';
  h+='</div>';
  return h;
}
function renderEvidenceReview(r){
  const ref=r.approved_references;
  let h='<div id="evidence-review"><h4>Equipment evidence review</h4>';
  h+='<p class="muted" id="review-readonly">Read-only: this review writes nothing, opens no review case, and calls no model. It states what the supplied records support and which questions stay open.</p>';
  h+='<h4>What the supplied evidence supports</h4>';
  h+='<p class="muted" id="review-supported">'+escapeHtml(r.supported_evidence.statement)+'</p>';
  h+='<p class="muted">Units: '+escapeHtml(String(r.supported_evidence.units_status))+' · timestamp timezone: '+escapeHtml(String(r.supported_evidence.timestamp_timezone_status))+'</p>';
  h+='<table class="data-table" id="review-claims"><thead><tr><th>Fact / calculation</th><th>Basis</th><th>Citations</th><th>Scope</th></tr></thead><tbody>';
  r.cited_claims.forEach(c=>{
    const scope=c.computation?escapeHtml(String(c.computation.formula))+' over '+c.computation.input_count+' input(s)':'exact-ID relationship';
    h+='<tr><td>'+escapeHtml(c.text)+'</td><td>'+escapeHtml(c.kind)+' · '+escapeHtml(c.support.relevance)+'</td><td>'+c.citations.length+' ('+escapeHtml(c.support.checks.join(', '))+')</td><td class="muted">'+scope+'</td></tr>';
  });
  h+='</tbody></table>';
  h+='<h4>Approved references</h4>';
  h+='<p class="muted" id="review-references">'+escapeHtml(ref.state)+' — '+escapeHtml(ref.statement)+'</p>';
  if(ref.items.length){h+='<ul class="quality">'+ref.items.map(i=>'<li>'+escapeHtml(i.title||i.chunk_id)+' — '+escapeHtml(String(i.source_id||''))+'</li>').join('')+'</ul>';}
  h+='<p class="muted">Ledger context used to scope retrieval: '+escapeHtml((ref.ledger_context_terms||[]).join(', ')||'equipment type code only')+'.</p>';
  h+='<h4>Unresolved questions (limit only dependent conclusions)</h4>';
  h+='<ul class="quality" id="review-limitations">'+r.limitations.map(l=>'<li><strong>'+escapeHtml(l.dimension)+'</strong> — '+escapeHtml(String(l.status))+': '+escapeHtml(l.statement)+'</li>').join('')+'</ul>';
  h+='<h4>Non-operational checks a person could perform</h4>';
  if(r.human_checks.length){h+='<ul class="quality" id="review-checks">'+r.human_checks.map(c=>'<li>'+escapeHtml(c.question)+' <span class="muted">('+escapeHtml(c.topic)+' · '+escapeHtml(c.verify_action)+' · documentary, non-operational)</span></li>').join('')+'</ul>';}else{h+='<p class="muted" id="review-checks">No evidence-specific documentary check is register-backed for this asset.</p>';}
  h+='</div>';
  return h;
}
