// Manual asset mapping: exact-ID links stay distinct from manual assignments.
function mountAssetMapping(id,parent){document.querySelectorAll('.asset-mapping').forEach(n=>n.remove());const host=document.createElement('div');host.className='asset-mapping';parent.appendChild(host);renderAssetMapping(id,host);}
const MAPPING_KIND={exact_id:'Exact-ID link',manually_assigned:'Manually assigned',unresolved:'Unresolved'};
async function renderAssetMapping(id,host){host.innerHTML='<h4>Linked source records</h4><p class="muted">Loading…</p>';try{const r=await fetch('/api/asset-mappings/equipment/'+encodeURIComponent(id));const j=await r.json();if(!r.ok)throw new Error(j.error||'Mapping load failed');let h='<h4>Linked source records</h4>';h+='<p class="muted">Exact-ID links come from matching source ID strings. Manual assignments are recorded by a person; they are not source-confirmed and not verified.</p>';if(!j.groups.length)h+='<p class="muted" id="mapping-none">No linked source records for this equipment.</p>';j.groups.forEach(g=>{h+=`<h5>${escapeHtml(g.family_label)}</h5><ul class="quality mapping-links">`;g.links.forEach(l=>{const det=['Kind: '+(MAPPING_KIND[l.link_kind]||l.link_kind)];if(l.basis)det.push('Basis: '+escapeHtml(l.basis));if(l.basis_origin)det.push('Basis origin: '+escapeHtml(l.basis_origin));if(l.actor&&l.actor.label)det.push('Recorded by '+escapeHtml(l.actor.label)+' (self-asserted, unverified)');if(l.source_sha256)det.push('Source hash '+escapeHtml(String(l.source_sha256).slice(0,12))+'…');if(l.source_changed)det.push('Source content has changed since this mapping was recorded');if(l.source_available===false)det.push('Source record is no longer available');if(l.verification_status)det.push('Verification: '+escapeHtml(l.verification_status));if(l.method)det.push('Method: '+escapeHtml(l.method));h+=`<li data-link="${escapeHtml(l.mapping_id||'exact')}"><span class="severity">${escapeHtml(MAPPING_KIND[l.link_kind]||l.link_kind)}</span> <strong>${escapeHtml(l.source_record_label||l.source_record_key)}</strong><br><span class="muted">${det.join(' · ')}</span>`;if(l.identity_caveat)h+='<br><span class="muted">'+escapeHtml(l.identity_caveat)+'</span>';if(j.writes_enabled&&l.mapping_id){h+=`<br><button data-edit="${escapeHtml(l.mapping_id)}">Edit basis</button> <button data-undo="${escapeHtml(l.mapping_id)}">Remove</button>`;}else if(l.mapping_id){h+='<br><span class="muted">Editing is disabled in this deployment.</span>';}h+='</li>';});h+='</ul>';});h+='<h4>Find unlinked source records</h4>';if(j.writes_enabled){h+='<p class="muted">Search returns clues only; it never proves a link. Choose a record, review its original fields, and record the basis.</p>';h+='<div class="queue-filters"><input id="mapping-search" placeholder="Filter candidate records…"><input id="mapping-actor" placeholder="Your name/label (self-asserted)"><button id="mapping-search-btn">Search</button></div><div id="mapping-candidates"><p class="muted">Loading candidates…</p></div>';}else{h+='<p class="muted" id="mapping-disabled">Manual assignment is disabled in this deployment. '+escapeHtml(j.manual_enable_hint||'')+'</p>';}if(j.unavailable_families&&j.unavailable_families.length)h+='<h4>Unavailable source families</h4><ul class="quality" id="mapping-unavailable">'+j.unavailable_families.map(f=>`<li><strong>${escapeHtml(f.label)}</strong> — ${escapeHtml(f.note)}</li>`).join('')+'</ul>';host.innerHTML=h;host.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>removeMapping(b.dataset.undo,id,host));host.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editMapping(b.dataset.edit,id,host));if(j.writes_enabled){const box=host.querySelector('#mapping-candidates');const load=()=>loadMappingCandidates(id,host,box,document.getElementById('mapping-search').value);host.querySelector('#mapping-search-btn').onclick=load;load();}}catch(e){host.innerHTML='<h4>Linked source records</h4><p class="muted">'+escapeHtml(e.message)+'</p>';}}
async function loadMappingCandidates(id,host,box,q){box.innerHTML='<p class="muted">Loading candidates…</p>';try{const r=await fetch('/api/asset-mappings/candidates?exclude_linked=true&limit=30&q='+encodeURIComponent(q||''));const j=await r.json();if(!r.ok)throw new Error(j.error||'Candidate load failed');if(!j.items.length){box.innerHTML='<p class="muted">No unlinked source records match.</p>';return;}box.innerHTML=j.items.map(it=>{const idf=Object.entries(it.original_identifiers||{}).map(([k,v])=>escapeHtml(k)+': '+escapeHtml(String(v))).join(' · ');const flds=Object.entries(it.fields||{}).slice(0,6).map(([k,v])=>escapeHtml(k)+'='+escapeHtml(Array.isArray(v)?v.join(','):String(v))).join(' · ');const action=it.assignable?'Assign':'Record as unresolved';return `<article class="defect-item"><div class="defect-top"><strong>${escapeHtml(it.record_label)}</strong><span class="severity">${escapeHtml(it.family_label)}</span></div><p class="muted">${idf}</p><p class="muted">${flds}</p><p class="muted">${escapeHtml(it.scope_note)}</p><label>Basis for this assignment <input class="mapping-basis" placeholder="e.g. Confirmed by meter serial on site"></label> <button class="mapping-assign" data-family="${escapeHtml(it.source_family)}" data-key="${escapeHtml(it.source_record_key)}" data-assignable="${it.assignable}">${action}</button><span class="mapping-msg muted"></span></article>`;}).join('');box.querySelectorAll('.mapping-assign').forEach(b=>b.onclick=()=>assignMapping(id,host,b));}catch(e){box.innerHTML='<p class="muted">'+escapeHtml(e.message)+'</p>';}}
async function assignMapping(id,host,btn){const article=btn.closest('article');const basis=article.querySelector('.mapping-basis').value;const msg=article.querySelector('.mapping-msg');msg.textContent='';btn.disabled=true;try{const actorEl=document.getElementById('mapping-actor');const body={target_equipment_id:id,source_family:btn.dataset.family,source_record_key:btn.dataset.key,basis:basis,actor:(actorEl&&actorEl.value)||'local user'};if(btn.dataset.assignable!=='true')body.status='unresolved';const r=await fetch('/api/asset-mappings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Assignment failed');renderAssetMapping(id,host);}catch(e){msg.textContent=e.message;btn.disabled=false;}}
async function editMapping(mid,id,host){const basis=window.prompt('Update the basis for this assignment:');if(basis===null)return;try{const g=await fetch('/api/asset-mappings/'+encodeURIComponent(mid)).then(r=>r.json());const r=await fetch('/api/asset-mappings/'+encodeURIComponent(mid),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({from_version:g.version,basis:basis})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Edit failed');renderAssetMapping(id,host);}catch(e){window.alert(e.message);}}
async function removeMapping(mid,id,host){const note=window.prompt('Remove this manual assignment? Optional short reason:','');if(note===null)return;try{const g=await fetch('/api/asset-mappings/'+encodeURIComponent(mid)).then(r=>r.json());const r=await fetch('/api/asset-mappings/'+encodeURIComponent(mid)+'/remove',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({from_version:g.version,note:note||undefined})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Remove failed');renderAssetMapping(id,host);}catch(e){window.alert(e.message);}}

// Context-grounded Gemini review: deterministic evidence stays visibly separate
// from model-generated text. Every model string is escaped; abstentions and the
// no-approved-knowledge state are shown plainly.
const GEMINI_SECTION_LABELS={supporting_points:'Evidence supporting the answer',unknowns:'Unknowns and evidence gaps',human_checks:'Checks a person could verify'};
const geminiReviewCache=Object.create(null),geminiReviewInFlight=Object.create(null);
function mountGeminiReview(id,parent){document.querySelectorAll('.gemini-review').forEach(n=>n.remove());const host=document.createElement('div');host.className='gemini-review';parent.appendChild(host);renderGeminiReview(id,host);}
function geminiReviewUrl(id){return '/api/assets/'+encodeURIComponent(id)+'/gemini-review';}
function renderGeminiReview(id,host){
  let h='<h4>Grounded evidence explanation (Gemini)</h4>';
  h+='<p class="muted">Model-generated text that explains only the evidence supplied below. It is unverified, is not a diagnosis, and is not a maintenance instruction.</p>';
  if(!window.GEMINI_REVIEW_ENABLED){h+='<p class="muted" id="gemini-review-disabled">The context-grounded Gemini review is not enabled in this deployment.</p>';host.innerHTML=h;return;}
  h+='<button id="gemini-review-button">AI summary preview</button> <span class="muted" id="gemini-review-msg"></span>';
  h+='<div id="gemini-review-result"></div>';
  host.innerHTML=h;
  document.querySelector('#gemini-review-button').onclick=()=>generateGeminiReview(id,host);
}
async function generateGeminiReview(id,host){
  const btn=document.querySelector('#gemini-review-button'),msg=document.querySelector('#gemini-review-msg'),box=document.querySelector('#gemini-review-result');
  if(!btn||!msg||!box)return false;
  if(geminiReviewCache[id]){box.innerHTML=renderGeminiReviewResult(id,geminiReviewCache[id]);return geminiReviewCache[id].model_generated===true&&['explained','abstained'].includes(geminiReviewCache[id].status);}
  btn.disabled=true;msg.textContent='Requesting an explanation of the supplied evidence...';box.innerHTML='';
  try{
    if(!geminiReviewInFlight[id])geminiReviewInFlight[id]=(async()=>{const r=await fetch(geminiReviewUrl(id),{method:'POST'});const j=await r.json();if(!r.ok)throw new Error(j.error||'Model review failed');if(j.status!=='rejected')geminiReviewCache[id]=j;return j;})();
    const j=await geminiReviewInFlight[id];
    box.innerHTML=renderGeminiReviewResult(id,j);
    return j.model_generated===true&&['explained','abstained'].includes(j.status);
  }catch(e){box.innerHTML='<p class="muted">'+escapeHtml(e.message)+'</p>';return false;}
  finally{delete geminiReviewInFlight[id];if(btn.isConnected)btn.disabled=false;if(msg.isConnected)msg.textContent='';}
}
function syncAssistantState(){
  const idInput=document.querySelector('#assistant-asset-id'),status=document.querySelector('#assistant-status'),agentStatus=document.querySelector('#assistant-agent-status'),send=document.querySelector('#assistant-send');
  if(!idInput||!status||!agentStatus||!send)return;
  if(currentAsset)idInput.value=currentAsset;
  const agent=window.AGENT_DRAFT_ENABLED===true,gemini=window.GEMINI_REVIEW_ENABLED===true;
  send.disabled=!(agent&&gemini);
  status.textContent=currentAsset?'Selected equipment: '+currentAsset+'. You can also enter another telemetry-backed asset ID.':'Enter or select a telemetry-backed asset to begin.';
  agentStatus.textContent=!agent?'The deterministic evidence agent is disabled in this deployment.':(!gemini?'The Gemini explanation service is disabled in this deployment.':'Ready: the deterministic agent prepares the evidence; Gemini explains only checked evidence after you press Send.');
}
function assistantMessage(className,label,html){
  const transcript=document.querySelector('#assistant-transcript'),article=document.createElement('article');
  article.className='chat-message '+className;
  const small=document.createElement('small');small.textContent=label;article.appendChild(small);
  const body=document.createElement('div');body.innerHTML=html;article.appendChild(body);transcript.appendChild(article);article.scrollIntoView({block:'nearest'});return article;
}
function renderAgentDraft(draft){
  let h='<p><strong>Evidence agent · '+escapeHtml(String(draft.status||'unknown'))+'</strong></p>';
  h+='<p>'+escapeHtml(String(draft.summary||draft.message||'No summary returned.'))+'</p>';
  h+='<p class="muted">'+(draft.claims||[]).length+' supported claims · '+(draft.suggestions||[]).length+' documentary checks · '+(draft.known_gaps||[]).length+' evidence gaps. Human review remains required.</p>';
  if((draft.claims||[]).length)h+='<ul class="quality">'+draft.claims.slice(0,5).map(c=>'<li>'+escapeHtml(String(c.text||''))+'</li>').join('')+'</ul>';
  return h;
}
function renderAssistantItems(items){
  if(!(items||[]).length)return '<p class="muted">No supported item.</p>';
  return '<ul class="quality">'+items.map(it=>'<li>'+escapeHtml(String(it.text||''))+' <span class="muted">['+geminiCitations(it.citations)+']</span></li>').join('')+'</ul>';
}
function renderAssistantGemini(result){
  let h='<p><strong>Gemini · '+escapeHtml(String(result.status||'unknown'))+'</strong></p>';
  h+='<p class="muted">'+(result.model_generated!==true?'No model answer was produced; the deterministic evidence above is unaffected.':(result.explanation_accepted!==true?'Gemini returned output, but the app accepted no answer from it, so no model text is shown. The deterministic evidence above is unaffected.':'The answer below is grounded in the cited evidence and requires human review.'))+'</p>';
  if(result.reason_message)h+='<p>'+escapeHtml(String(result.reason_message))+'</p>';
  const answer=result.direct_answer;
  h+='<h5>Direct answer</h5>';
  if(answer&&String(answer.text||'').trim())h+='<p id="assistant-direct-answer">'+escapeHtml(String(answer.text))+' <span class="muted">['+geminiCitations(answer.citations)+']</span></p>';
  else h+='<p class="muted" id="assistant-direct-answer">No accepted direct answer is shown.</p>';
  const sections=result.sections||{};
  h+='<h5>Evidence behind the answer</h5>'+renderAssistantItems(sections.supporting_points);
  h+='<h5>Unknowns and evidence gaps</h5>'+renderAssistantItems(sections.unknowns);
  h+='<h5>Checks a person could verify</h5>'+renderAssistantItems(sections.human_checks);
  if(result.no_relevant_reference)h+='<p class="muted" id="assistant-no-reference">No approved engineering reference applies to this question, so the answer is limited to supported observations and documented gaps.</p>';
  const sel=result.evidence_selection||{};
  if(sel.selected_facts!==undefined&&sel.total_facts!==undefined)h+='<p class="muted" id="assistant-selection">'+escapeHtml(String(sel.selected_facts))+' of '+escapeHtml(String(sel.total_facts))+' deterministic facts were relevant to this question'+(sel.selected_references?' · '+escapeHtml(String(sel.selected_references))+' approved reference(s) supplied':'')+'.</p>';
  return h;
}
async function submitAssistantQuestion(event){
  event.preventDefault();
  const asset=document.querySelector('#assistant-asset-id').value.trim(),question=document.querySelector('#assistant-question').value.trim(),error=document.querySelector('#assistant-error'),send=document.querySelector('#assistant-send');
  error.hidden=true;error.textContent='';
  if(!asset){error.textContent='Enter a telemetry-backed equipment ID.';error.hidden=false;return;}
  if(!question||question.length>500){error.textContent='Enter a question of 1–500 characters.';error.hidden=false;return;}
  if(window.AGENT_DRAFT_ENABLED!==true||window.GEMINI_REVIEW_ENABLED!==true){error.textContent='The assistant is unavailable because a required service is disabled.';error.hidden=false;return;}
  assistantMessage('user-message','You',escapeHtml(question));
  const response=assistantMessage('agent-message','Evidence assistant','<p class="muted">Preparing checked context and evidence…</p>');
  send.disabled=true;showScreen('chat');
  try{
    const contextResponse=await fetch('/api/agent/context/'+encodeURIComponent(asset));
    const bundle=await contextResponse.json();if(!contextResponse.ok)throw new Error(bundle.error||'Checked asset context is unavailable.');
    const draftResponse=await fetch('/api/agent/draft/'+encodeURIComponent(asset));
    const draft=await draftResponse.json();if(!draftResponse.ok)throw new Error(draft.error||'Evidence draft is unavailable.');
    if(draft.status==='rejected')throw new Error('The evidence agent rejected this asset context ('+String(draft.reason_code||'contract check')+'). No model request was sent.');
    response.querySelector('div').innerHTML=renderAgentDraft(draft)+'<p class="muted">Context bundle '+escapeHtml(String(bundle.bundle_version||''))+' · '+((bundle.evidence_items||[]).length)+' evidence items.</p><p class="muted">Requesting a grounded explanation…</p>';
    const modelResponse=await fetch(geminiReviewUrl(asset),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question})});
    const result=await modelResponse.json();if(!modelResponse.ok)throw new Error(result.error||'Gemini review failed.');
    response.querySelector('div').innerHTML=renderAgentDraft(draft)+'<p class="muted">Context bundle '+escapeHtml(String(bundle.bundle_version||''))+' · '+((bundle.evidence_items||[]).length)+' evidence items.</p>'+renderAssistantGemini(result);
    document.querySelector('#assistant-question').value='';
  }catch(e){response.querySelector('div').innerHTML='<p class="muted">'+escapeHtml(e.message)+'</p>';}
  finally{syncAssistantState();}
}
document.querySelector('#assistant-form')?.addEventListener('submit',submitAssistantQuestion);
function geminiCitations(citations){return (citations||[]).map(c=>'<code>'+escapeHtml(String(c.kind))+':'+escapeHtml(String(c.id))+'</code>').join(' ');}
function geminiModelAttribution(j){
  const model=escapeHtml(String(j.model||'model'));
  const head='<strong>Model status:</strong> '+escapeHtml(String(j.status))+(j.reason_code?' · '+escapeHtml(String(j.reason_code)):'');
  if(j.model_generated!==true){
    const d=j.diagnostics||{},bits=[];
    if(d.category)bits.push('category '+escapeHtml(String(d.category)));
    if(d.provider_status)bits.push('provider '+escapeHtml(String(d.provider_status)));
    if(d.http_status!==null&&d.http_status!==undefined)bits.push('HTTP '+escapeHtml(String(d.http_status)));
    return '<p class="muted" id="gemini-review-status">'+head+' — the model request failed, so no model output was produced'+(bits.length?' ('+bits.join(', ')+')':'')+'. No text was generated by any model; the deterministic evidence below is unaffected. A person must still review it.</p>';
  }
  if(j.explanation_accepted!==true){
    return '<p class="muted" id="gemini-review-status">'+head+' — Gemini returned output, but the app accepted no explanation from it, so no model text is shown; the deterministic evidence below is unaffected. A person must still review it.</p>';
  }
  return '<p class="muted" id="gemini-review-status">'+head+' — Gemini returned output and the app accepted the explanation, generated by '+model+(j.model_route==='fallback'?' (fallback used)':'')+'; a person must verify it.</p>';
}
function renderGeminiReviewResult(id,j){
  const det=j.supported_context||{},k=j.knowledge_state||{};
  let h='<div id="gemini-model-review">';
  h+=geminiModelAttribution(j);
  if(j.reason_message)h+='<p class="muted" id="gemini-review-reason">'+escapeHtml(String(j.reason_message))+'</p>';
  h+='<p class="muted" id="gemini-review-knowledge">'+(j.no_approved_knowledge?'No approved relevant knowledge is available for this equipment. The model may restate the observed evidence and list gaps only; it makes no engineering interpretation.':'Approved, reviewed references are available and may be cited with a verbatim quote.')+'</p>';
  h+='<h4>Deterministic evidence (not model-generated)</h4><div id="gemini-deterministic">';
  h+='<table class="data-table"><thead><tr><th>Fact / calculation</th><th>Basis</th><th>Citations</th></tr></thead><tbody>'+((det.cited_claims||[]).map(c=>'<tr><td>'+escapeHtml(c.text)+'</td><td>'+escapeHtml(c.kind)+' · '+escapeHtml(c.support?c.support.relevance:'')+'</td><td>'+((c.citations||[]).length)+'</td></tr>').join('')||'<tr><td colspan="3" class="muted">No deterministic fact is supported for this asset.</td></tr>')+'</tbody></table>';
  const link=det.link||{};h+='<p class="muted" id="gemini-review-link">Evidence link: '+escapeHtml(String(link.status||''))+' · method '+escapeHtml(String(link.matching_method||''))+' · verification '+escapeHtml(String(link.verification_status||''))+'. '+escapeHtml(String(link.caveat||''))+'</p>';
  h+='</div>';
  h+=(j.explanation_accepted===true?'<h4>Model-generated explanation (unverified)</h4>':(j.model_generated===true?'<h4>Model output withheld (no accepted explanation)</h4>':'<h4>Model output: none (request failed)</h4>'))+'<div id="gemini-model-sections">';
  if(j.direct_answer&&String(j.direct_answer.text||'').trim())h+='<h5>Direct answer</h5><p id="gemini-direct-answer">'+escapeHtml(String(j.direct_answer.text))+' <span class="muted">['+geminiCitations(j.direct_answer.citations)+']</span></p>';
  if(j.no_relevant_reference)h+='<p class="muted" id="gemini-no-reference">No approved engineering reference applies, so the answer is limited to supported observations and documented gaps.</p>';
  GEMINI_SECTION_LABELS && Object.keys(GEMINI_SECTION_LABELS).forEach(name=>{const items=(j.sections||{})[name]||[];h+='<h5>'+escapeHtml(GEMINI_SECTION_LABELS[name])+'</h5>';if(!items.length){h+='<p class="muted" id="gemini-section-'+name+'">No supported item in this section.</p>';return;}h+='<ul class="quality" id="gemini-section-'+name+'">'+items.map(it=>'<li>'+escapeHtml(it.text)+' <span class="muted">['+geminiCitations(it.citations)+']</span>'+(it.quotes&&it.quotes.length?'<br><span class="muted">Quote: '+escapeHtml(it.quotes.join(' … '))+'\u2019</span>':'')+'</li>').join('')+'</ul>';});
  h+='</div>';
  if((j.omitted||[]).length)h+='<p class="muted" id="gemini-review-omitted">'+j.omitted.length+' model item(s) were omitted because they could not be matched to the supplied evidence.</p>';
  h+='</div>';
  return h;
}

